import sys

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def is_possible(A, B, C):
    gcd_AB = gcd(A, B)
    if C % gcd_AB == 0:
        return "YES"
    else:
        return "NO"

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    A = int(data[0])
    B = int(data[1])
    C = int(data[2])
    result = is_possible(A, B, C)
